uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float density : 0.0 .. 1.0 = 0.4;
uniform float brightness : 0.0 .. 1.0 = 1.0;
uniform vec3 tint : color = 1.0, 1.0, 0.9;

state fixed phase[32];
state bool inited;

void update() {
  if (!inited) {
    for (int i = 0; i < 32; i = i + 1) {
      phase[i] = fixed(hash(float(i) * 17.0));
    }
    inited = true;
  }
  for (int i = 0; i < 32; i = i + 1) {
    phase[i] = fract(phase[i] + fixed(dt * speed * 0.0625));
  }
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);
  vec3 c = vec3(0.0, 0.0, 0.0);
  for (int i = 0; i < 32; i = i + 1) {
    fixed p = fract(s * fixed(32.0) + phase[i]);
    fixed w = p * fixed(256.0);
    w = w * (fixed(1.0) - w);
    w = w * fixed(4.0);
    if (w > fixed(0.9)) {
      c = c + vec3(1.0, 1.0, 1.0) * float(w);
    }
  }
  c = c * vec3(float(fixed(brightness)), float(fixed(brightness)), float(fixed(brightness)));
  c = c * tint;
  return clamp(c, vec3(0.0, 0.0, 0.0), vec3(1.0, 1.0, 0.0));
}
